parameters.jsCode:
const googleForm = $('HTTP Request1').first().json;
const quiz = $('Code in JavaScript').first().json;

const questionIds = googleForm.replies
  .map(reply => reply.createItem?.questionId?.[0])
  .filter(Boolean);

const questions = quiz.questions;

if (questionIds.length !== questions.length) {
  throw new Error(
    `Question count mismatch: Google Forms returned ${questionIds.length} question IDs, but the quiz contains ${questions.length} questions.`
  );
}

const requests = questions.map((q, i) => {
  const options = q.options.map(option => ({
    value: option
  }));

  const correctAnswer = q.options[q.correct_answer_index];

  return {
    updateItem: {
      item: {
        itemId: googleForm.replies[i].createItem.itemId,
        questionItem: {
          question: {
            questionId: questionIds[i],
            choiceQuestion: {
              type: "RADIO",
              options: options
            },
            grading: {
              pointValue: 1,
              correctAnswers: {
                answers: [
                  {
                    value: correctAnswer
                  }
                ]
              }
            }
          }
        }
      },
      location: {
        index: i
      },
      updateMask:
        "questionItem.question.choiceQuestion.options,questionItem.question.grading"
    }
  };
});

return [
  {
    json: {
      requests
    }
  }
];
